CREATE TABLE "better_supabase"."pass_check_ins" (
  "id"            uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"     uuid                     NOT NULL,
  "pass_id"       uuid                     NOT NULL,
  "resource_id"   uuid,
  "booking_id"    uuid,
  "gate"          text,
  "method"        text                     NOT NULL,
  "admitted"      boolean                  NOT NULL,
  "reason"        text,
  "checked_in_by" uuid,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "pass_check_ins_check" CHECK ((admitted = (reason IS NULL))),
  CONSTRAINT "pass_check_ins_gate_check" CHECK (((gate IS NULL) OR ((length(gate) >= 1) AND (length(gate) <= 100)))),
  CONSTRAINT "pass_check_ins_method_check" CHECK ((method = ANY (ARRAY['qr'::text, 'nfc'::text, 'manual'::text]))),
  CONSTRAINT "pass_check_ins_pkey" PRIMARY KEY (id),
  CONSTRAINT "pass_check_ins_reason_check"
    CHECK
    (((reason IS NULL) OR (reason = ANY (ARRAY['invalid'::text, 'revoked'::text, 'not_yet_valid'::text, 'expired'::text, 'used_up'::text, 'booking_cancelled'::text,
    'booking_unconfirmed'::text, 'outside_window'::text, 'wrong_resource'::text, 'full'::text]))))
);

ALTER TABLE "better_supabase"."pass_check_ins"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."passes" (
  "id"             uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "tenant_id"      uuid                     NOT NULL,
  "kind"           text                     NOT NULL DEFAULT 'ticket'::text,
  "holder_user_id" uuid,
  "holder_name"    text,
  "holder_email"   text,
  "subject_type"   text,
  "subject_id"     text,
  "booking_id"     uuid,
  "resource_id"    uuid,
  "uses_allowed"   integer,
  "uses"           integer                  NOT NULL DEFAULT 0,
  "valid_from"     timestamp with time zone NOT NULL DEFAULT now(),
  "valid_until"    timestamp with time zone,
  "status"         text                     NOT NULL DEFAULT 'active'::text,
  "nonce"          text                     NOT NULL,
  "issued_by"      uuid,
  "created_at"     timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"     timestamp with time zone NOT NULL DEFAULT now(),
  "revoked_at"     timestamp with time zone,
  CONSTRAINT "passes_check1" CHECK (((uses_allowed IS NULL) OR (uses <= uses_allowed))),
  CONSTRAINT "passes_check2" CHECK (((valid_until IS NULL) OR (valid_until > valid_from))),
  CONSTRAINT "passes_check" CHECK (((subject_type IS NULL) = (subject_id IS NULL))),
  CONSTRAINT "passes_holder_email_check"
    CHECK (((holder_email IS NULL) OR ((length(holder_email) >= 3) AND (length(holder_email) <= 320) AND (POSITION(('@'::text) IN (holder_email)) > 1)))),
  CONSTRAINT "passes_holder_name_check" CHECK (((holder_name IS NULL) OR ((length(holder_name) >= 1) AND (length(holder_name) <= 200)))),
  CONSTRAINT "passes_kind_check" CHECK ((kind ~ '^[a-z][a-z0-9_-]{0,39}$'::text)),
  CONSTRAINT "passes_nonce_key" UNIQUE (nonce),
  CONSTRAINT "passes_pkey" PRIMARY KEY (id),
  CONSTRAINT "passes_status_check" CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text]))),
  CONSTRAINT "passes_subject_id_check" CHECK (((subject_id IS NULL) OR ((length(subject_id) >= 1) AND (length(subject_id) <= 200)))),
  CONSTRAINT "passes_subject_type_check" CHECK (((subject_type IS NULL) OR (subject_type ~ '^[a-z][a-z0-9_-]{0,62}$'::text))),
  CONSTRAINT "passes_uses_allowed_check" CHECK (((uses_allowed IS NULL) OR (uses_allowed > 0))),
  CONSTRAINT "passes_uses_check" CHECK ((uses >= 0))
);

